task_context.problem_statement:
Find the area of the parallelogram generated by $\begin{pmatrix} 3 \\ 1 \\ -2 \end{pmatrix}$ and $\begin{pmatrix} 1 \\ -3 \\ 4 \end{pmatrix}.$

[asy]
unitsize(0.4 cm);

pair A, B, C, D;

A = (0,0);
B = (7,2);
C = (1,3);
D = B + C;

draw(A--B,Arrow(6));
draw(A--C,Arrow(6));
draw(B--D--C);
[/asy]

